    let n = errno?;
    if RELOAD_REFUSALS.contains(&n) {
        Some(Refusal::Permanent)
    } else if RELOAD_TRANSIENT.contains(&n) {
        Some(Refusal::Transient)
    } else {
        None
    }
}
